reasons={
'Q021':'All unlimited supplies/tracks, limited-supply fallback and public/hidden information exceptions are covered in the same-entry Components passage.',
'Q022':'The complete trade table and transfer/blackmail passage cover every permitted and prohibited asset and both share-piece destinations.',
'Q023':'The same-entry agreement table covers enforceability, promise timing and ability limits, simultaneous calls and the transfer activation restriction.',
'Q024':'All setup-card additions, holding destinations, luxury points and combined-deck display details are supplied.',
'Q025':'The answer gives both end triggers, immediate ordinary failure, both phase-completion exceptions and the explicit Final Scoring prohibitions. Standing reaching failure identifies the failure endpoint; the location adjective adds no different trigger.',
'Q026':'The Power paragraph covers all enterprises (including applicable prestige enterprises), Company shares, track rates, token/card sources and all award/tiebreak branches.',
'Q027':'The Court/workshop and outcome rows correctly distinguish survival and failure scoring and final retirement procedures.',
'Q028':'Spouse permanence and transfer restrictions, immediate trades and personal stackable discounts with both frequency limits are covered. Retirement discounts reducing actual spending conveys applying the card discount to retirement cost; no different amount is asserted.',
'Q029':'Both causes expressly leave the fitted ship in play and bar purchasing its returned yard until that ship returns.',
'Q030':'The exhaustive action table supplies all prices, placements, enterprise types, votes, bonuses and failure scoring. Writer/officer rows require only placing a member and specify no payment, clearly conveying free enlistment alongside the explicit purchase payments.',
'Q031':'The mandatory prize-member fallback and VP loss are explicit, as are the no-action and marker-return outcomes.',
'Q032':'The direct conclusion and full Hiring passage cover automatic return, supply/prize priority, prize VP loss and inability to appoint anyone.',
'Q033':'The complete Hiring table supplies every requested hiring actor, candidate pool, ordered fallback and Commander exclusion.',
'Q034':'All success choices, immediate China hiring, repeated Envoys and the post-Envoy transfer timing are explicit.',
'Q035':'The Military Affairs paragraph supplies action order, strict-exceedance and vacancy triggers, largest-family selection, both piece destinations, incumbent ties and Nepotism exemption.',
'Q036':'The Presidency paragraph supplies ordering authority, mandatory opportunities, decline rights, uninterrupted positions and all vacant-President Chairman limits.',
'Q037':'Refresh explicitly preserves writer affiliation, returns dividers to supply and states that Trade never exhausts ships.',
'Q038':'The complete alliance lifecycle covers start timing, approval and funding, active placement, whole-piece exhaustion, purchase-turn once-only use for either purpose and unused-alliance exhaustion at Refresh.',
'Q039':'The own-Company-region passage explicitly gives zero defense penalty, surviving-officer-plus-Commander minimum loot and zero tower trophies.',
'Q040':'The Governor options table explicitly gives the two construction stages and destinations and every requested regiment property.'
}
grades=[]
assert len(p['entries'])==20
for e in p['entries']:
    q=e['id']; rows=chosen[q]
    assert [x[0] for x in rows]==e['requested_fact_scope_entry']['material_requested_facts'],q
    answer=e['reader_b_entry']['answer']
    parts=[]
    for req,quote in rows:
        assert quote and quote in answer,(q,req,quote)
        parts.append({'requirement':req,'status':'covered','reader_quotes':[quote]})
    grades.append({'id':q,'grade':'Correct','reason':reasons[q],'material_parts':parts,'unsupported_guesses':[],'summary_issue_if_any':None})
out={'block_id':'block-02','readers':{'reader-b':{'grades':grades}}}
path=base/'grades-same-entry.json'
text=json.dumps(out,ensure_ascii=False,indent=2)+'\n'
path.write_text(text)
print(json.dumps({'path':str(path),'grades':len(grades),'material_parts':sum(len(g['material_parts']) for g in grades),'sha256':hashlib.sha256(text.encode()).hexdigest()}))